import{c as a,Z as g,Q as e,j as i,g as o,n as r,o as s,av as d,m as l}from"./chunks/framework.rWdQudnF.js";const f=JSON.parse('{"title":"架构设计方法","description":"","frontmatter":{"title":"架构设计方法"},"headers":[],"relativePath":"综合知识/架构设计/架构设计方法.md","filePath":"综合知识/架构设计/架构设计方法.md","lastUpdated":null}'),h={name:"综合知识/架构设计/架构设计方法.md"},p={id:"absd-—-基于架构的软件设计",tabindex:"-1"};function b(u,t,q,S,c,k){const n=g("font");return e(),i("div",null,[o("h3",p,[t[1]||(t[1]=r("ABSD — ",-1)),s(n,{color:"#ff0000"},{default:d(()=>[...t[0]||(t[0]=[r("基于架构的软件设计",-1)])]),_:1}),t[2]||(t[2]=r()),t[3]||(t[3]=o("a",{class:"header-anchor",href:"#absd-—-基于架构的软件设计","aria-label":'Permalink to "ABSD — <font color="#ff0000">基于架构的软件设计</font>"'},"​",-1))]),t[16]||(t[16]=l('<blockquote><p>ABSD 方法是由<strong>商业、质量和功能需求</strong>的组合驱动的，是一个<strong>自顶向下、递归细化</strong>的方法，直到能产生<strong>软件构件和类</strong>。</p></blockquote><p><strong>ABSD 方法的三个基础：</strong></p><ol><li>对系统进行功能分解</li><li>采用<strong>架构策略</strong>实现质量属性与商业需求</li><li>采用软件模板设计软件结构</li></ol><p><strong>六个子过程：</strong></p><ol><li><strong>架构需求</strong> — 获取需求</li><li><strong>架构设计</strong> — 设计方案</li><li><strong>架构文档化</strong> — 输出架构规格说明和测试架构需求的质量设计说明书</li><li><strong>架构复审</strong> — 标识潜在风险，及早发现架构设计中的缺陷和错误</li><li><strong>架构实现</strong> — 编码实现</li><li><strong>架构演化</strong> — 应对需求变化，修改应用架构满足新需求</li></ol><hr><blockquote><p>ABSD 是架构设计的核心方法论，六个子过程和三基础是高频选择题考点。</p></blockquote><p>基于架构的软件开发方法</p><h4 id="absd-概述" tabindex="-1">ABSD 概述 <a class="header-anchor" href="#absd-概述" aria-label="Permalink to &quot;ABSD 概述&quot;">​</a></h4>',9)),o("p",null,[t[6]||(t[6]=r("ABSD方法是架构驱动，强调",-1)),t[7]||(t[7]=o("strong",null,"由业务、质量和功能需求的组合",-1)),t[8]||(t[8]=r("驱动架构设计。它强调",-1)),s(n,{color:"#ff0000"},{default:d(()=>[...t[4]||(t[4]=[r("采用视角和视图来描述软件架构",-1)])]),_:1}),t[9]||(t[9]=r("，采用用例和质量属性场景来描述需求。进一步来说，",-1)),s(n,{color:"#ff0000"},{default:d(()=>[...t[5]||(t[5]=[r("用例描述的是功能需求，质量属性场景描述的是质量需求",-1)])]),_:1}),t[10]||(t[10]=r("（或侧重于非功能需求）。",-1))]),t[17]||(t[17]=l('<p>使用ABSD方法，设计活动可以从项目总体功能框架明确就开始，这意味着需求获取和分析还没有完成，就开始了软件设计。</p><p>ABSD方法有三个基础。第一个基础是功能的分解，使用已有的基于模块的内聚和耦合技术；第二个基础是通过选择架构风格来实现质量和业务需求；第三个基础是软件模板的使用，软件模板利用了一些软件系统的结构。</p><p>ABSD方法是<strong>递归的</strong>，且迭代的每一个步骤都是清晰定义的。因此，不管设计是否完成，架构总是清晰的，有助于降低架构设计的随意性。</p><hr><blockquote><p>ABSD 方法是由<strong>商业、质量和功能需求</strong>的组合驱动的，是一个<strong>自顶向下、递归细化</strong>的方法，直到能产生<strong>软件构件和类</strong>。</p></blockquote><p><strong>ABSD 方法的三个基础：</strong></p><ol><li>对系统进行<strong>功能分解</strong></li><li>采用<strong>架构风格</strong>实现质量属性与商业需求</li><li>采用<strong>软件模板</strong>设计软件结构</li></ol><blockquote><p>⚠️ &quot;强调由业务、质量和功能需求的组合驱动&quot; 本身<strong>不属于</strong>三个基础（而是方法驱动因素）。</p></blockquote><h4 id="absd-六个子过程" tabindex="-1">ABSD 六个子过程 <a class="header-anchor" href="#absd-六个子过程" aria-label="Permalink to &quot;ABSD 六个子过程&quot;">​</a></h4>',9)),o("p",null,[t[12]||(t[12]=r("架构设计是在**",-1)),s(n,{color:"#ff0000"},{default:d(()=>[...t[11]||(t[11]=[r("需求分析之后，概要设计之前",-1)])]),_:1}),t[13]||(t[13]=r("**，是为了解决需求分析和软件设计之间的鸿沟问题。基于架构的软件开发过程可分为下列六步：",-1))]),t[18]||(t[18]=l('<p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517145011.png" alt="image.png"></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>架构需求 → 架构设计 → 架构文档化 → 架构复审 → 架构实现 → 架构演化</span></span></code></pre></div><table tabindex="0"><thead><tr><th>子过程</th><th>核心内容</th></tr></thead><tbody><tr><td><strong>1. 架构需求</strong></td><td>获取需求（质量目标 + 系统商业目标 + 开发人员商业目标）</td></tr><tr><td><strong>2. 架构设计</strong></td><td>设计方案</td></tr><tr><td><strong>3. 架构文档化</strong></td><td>输出<strong>架构规格说明书</strong> + <strong>测试架构需求的质量设计说明书</strong></td></tr><tr><td><strong>4. 架构复审</strong></td><td>标识潜在风险，及早发现缺陷和错误</td></tr><tr><td><strong>5. 架构实现</strong></td><td>编码实现（基于文档化后的架构说明书）</td></tr><tr><td><strong>6. 架构演化</strong></td><td>应对需求变化，需先进行<strong>需求变化归类</strong></td></tr></tbody></table><blockquote><p>⚠️ 标识构件的正确顺序：<strong>生成类图 → 对类进行分组 → 把类打包成构件</strong></p></blockquote><hr><p>架构需求：重在掌握<strong>标识构件</strong>的三步，如下左图。</p><p>架构设计：将需求阶段的标识构件映射成构件，进行分析，如下右图。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517145105.png" alt="image.png"></p><p>架构（体系结构）文档化：主要产出两种文档，</p><ul><li>即<strong>架构（体系结构）规格说明</strong>，</li><li>测试架构（体系结构)需求的<strong>质量设计说明书</strong>。</li></ul><p>文档是至关重要的，是所有人员通信的手段，关系开发的成败。</p><p>架构复审：<strong>由外部人员</strong>（独立于开发组织之外的人，如用户代表和领域专家等）参加的复审，复审架构是否满足需求，质量问题，构件划分合理性等。若复审不过，则返回架构设计阶段进行重新设计、文档化，再复审。</p><p>架构实现：用实体来显示出架构。实现构件，构件组装成系统，如下左图：</p><p>架构演化：对架构进行改变，按需求增删构件，使架构可复用，如下右图：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517145311.png" alt="image.png"></p><h4 id="架构-体系结构-文档化" tabindex="-1">架构（体系结构）文档化 <a class="header-anchor" href="#架构-体系结构-文档化" aria-label="Permalink to &quot;架构（体系结构）文档化&quot;">​</a></h4><p><strong>ABSD 中文档化核心输出：</strong></p><ol><li><strong>体系结构规格说明</strong></li><li><strong>测试架构需求的质量设计说明书</strong></li></ol><p><strong>文档化原则：</strong></p><ul><li>从使用者角度书写</li><li>随时保证文档最新</li><li>分发给相关人员</li><li>针对不同背景的人员书写方式不同</li></ul><h4 id="架构文档化" tabindex="-1">架构文档化 <a class="header-anchor" href="#架构文档化" aria-label="Permalink to &quot;架构文档化&quot;">​</a></h4><blockquote><p>架构文档化过程的主要输出结果是<strong>架构规格说明书</strong>和<strong>测试架构需求的质量设计说明书</strong>。</p></blockquote><p><strong>文档化原则：</strong></p><ul><li>从使用者的角度书写文档</li><li>随时保证文档是最新的</li><li>将文档分发给相关人员</li><li>针对不同背景的人员书写文档的方式不同</li></ul><h4 id="架构复审" tabindex="-1">架构复审 <a class="header-anchor" href="#架构复审" aria-label="Permalink to &quot;架构复审&quot;">​</a></h4><ul><li>目的：<strong>标识潜在风险</strong>，及早发现架构设计中的缺陷和错误</li><li>必须邀请：<strong>独立于系统开发的外部人员</strong>（领域专家）</li><li>复审过程由<strong>用户代表与领域专家</strong>决定架构是否满足需求</li></ul><hr><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260522155510.png" alt="image.png"></p><h4 id="架构描述与需求对应" tabindex="-1">架构描述与需求对应 <a class="header-anchor" href="#架构描述与需求对应" aria-label="Permalink to &quot;架构描述与需求对应&quot;">​</a></h4><table tabindex="0"><thead><tr><th>描述对象</th><th>使用工具</th></tr></thead><tbody><tr><td>架构</td><td><strong>视角与视图</strong></td></tr><tr><td>功能需求</td><td><strong>用例</strong></td></tr><tr><td>质量需求</td><td><strong>质量场景</strong></td></tr></tbody></table><h4 id="软件系统四大基本功能-三硬件构件" tabindex="-1">软件系统四大基本功能 + 三硬件构件 <a class="header-anchor" href="#软件系统四大基本功能-三硬件构件" aria-label="Permalink to &quot;软件系统四大基本功能 + 三硬件构件&quot;">​</a></h4><p><strong>四大基本功能（自上而下）：</strong></p><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td><strong>数据存储</strong></td><td>存储和检索数据</td></tr><tr><td><strong>数据访问逻辑</strong></td><td>处理访问数据的过程</td></tr><tr><td><strong>应用逻辑</strong></td><td>DFD/用例/功能需求中记录的业务逻辑</td></tr><tr><td><strong>表示逻辑</strong></td><td>向用户显示信息并接收用户命令</td></tr></tbody></table><p><strong>三硬件构件：</strong> 客户端（Clients）、服务器（Servers）、网络（Network）</p><hr><h3 id="dssa-—-特定领域软件架构" tabindex="-1">DSSA — 特定领域软件架构 <a class="header-anchor" href="#dssa-—-特定领域软件架构" aria-label="Permalink to &quot;DSSA — 特定领域软件架构&quot;">​</a></h3><blockquote><p>DSSA 是特定应用领域中为一组应用提供组织结构参考的<strong>标准软件架构</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>阶段</th><th>目标</th><th>产出</th></tr></thead><tbody><tr><td><strong>领域分析</strong></td><td>获得<strong>领域模型</strong>，描述领域中系统间的共同需求</td><td>领域模型</td></tr><tr><td><strong>领域设计</strong></td><td>获得<strong>特定领域软件架构（DSSA）</strong></td><td>领域架构</td></tr><tr><td><strong>领域实现</strong></td><td>开发和组织可重用信息，实现基础软件架构</td><td>可重用构件/资产</td></tr></tbody></table><p><strong>四类参与角色：</strong></p><ol><li><strong>领域专家</strong> — 提供领域知识</li><li><strong>领域分析者</strong> — 控制领域分析过程，进行知识获取，组织领域模型</li><li><strong>领域设计者</strong> — 根据领域模型开发领域设计，验证设计的准确性和一致性</li><li><strong>领域实现者</strong> — 实现可重用资产</li></ol><p><strong>DSSA 三级层次：</strong></p><ul><li>领域开发环境 → <strong>应用工程师</strong>主要在领域特定应用开发环境中工作</li><li>领域特定应用开发环境</li><li>应用执行环境</li></ul><p><strong>垂直域 vs 水平域：</strong></p><ul><li><strong>垂直域</strong>：定义了一个特定的系统族，包含整个系统族内的多个系统</li><li><strong>水平域</strong>：定义了多个系统和多个系统族中功能区域的共有部分，在子系统级上涵盖多个系统族</li></ul><hr><blockquote><p>DSSA 是特定领域中<strong>一组应用的标准软件架构</strong>，三步法和四角色是高频考点。</p></blockquote><p>DSSA就是专用于一类特定类型的任务（领域）的、在整个领域中能有效地使用的、为成功构造应用系统限定了标准的组合结构的软件构件的集合。 DSSA就是一个特定的问题领域中支持一组应用的领域模型、参考需求、参考架构等组成的开发基础，其目标就是<strong>支持在一个特定领域中多个应用的生成</strong>。</p><ul><li>垂直域：在一个特定领域中的通用的软件架构，是一个完整的架构。</li><li>水平域：在多个不同的特定领域之间的相同的部分的小工具（如购物和教育都有收费系统，收费系统即是水平域)。</li></ul><h4 id="dssa-三步法" tabindex="-1">DSSA 三步法 <a class="header-anchor" href="#dssa-三步法" aria-label="Permalink to &quot;DSSA 三步法&quot;">​</a></h4>',49)),o("p",null,[t[15]||(t[15]=r("DSSA 的三个基本活动：",-1)),s(n,{color:"#ff0000"},{default:d(()=>[...t[14]||(t[14]=[r(" 领域分析、领域设计、领域实现",-1)])]),_:1})]),t[19]||(t[19]=l('<table tabindex="0"><thead><tr><th>阶段</th><th>目标</th><th>产出</th><th>主要活动</th></tr></thead><tbody><tr><td><strong>领域分析</strong></td><td>获得<strong>领域模型</strong></td><td>领域模型</td><td>分析共性需求</td></tr><tr><td><strong>领域设计</strong></td><td>获得<strong>DSSA</strong></td><td>领域架构</td><td>高层次设计解决方案</td></tr><tr><td><strong>领域实现</strong></td><td>开发和组织<strong>可重用信息</strong></td><td>可重用构件/资产</td><td>实现可重用资产</td></tr></tbody></table><blockquote><p>⚠️ 领域设计的主要目标是<strong>获得 DSSA</strong>（不是领域模型）。建立过程是<strong>螺旋模型</strong>。</p></blockquote><h4 id="四类参与角色" tabindex="-1">四类参与角色 <a class="header-anchor" href="#四类参与角色" aria-label="Permalink to &quot;四类参与角色&quot;">​</a></h4><p>参与 DSSA 的四种角色人员</p><table tabindex="0"><thead><tr><th>角色</th><th>职责</th></tr></thead><tbody><tr><td><strong>领域专家</strong></td><td>提供领域知识、需求规约和实现知识</td></tr><tr><td><strong>领域分析者</strong></td><td>控制领域分析过程，组织领域模型</td></tr><tr><td><strong>领域设计者</strong></td><td>开发领域设计，验证准确性和一致性</td></tr><tr><td><strong>领域实现者</strong></td><td>实现可重用资产</td></tr></tbody></table><blockquote><p>⚠️ 最适合担任领域分析师的是：<strong>具有知识工程背景的有经验的系统分析员</strong></p></blockquote><h4 id="垂直域-vs-水平域" tabindex="-1">垂直域 vs 水平域 <a class="header-anchor" href="#垂直域-vs-水平域" aria-label="Permalink to &quot;垂直域 vs 水平域&quot;">​</a></h4><table tabindex="0"><thead><tr><th>类型</th><th>定义</th><th>范围</th></tr></thead><tbody><tr><td><strong>垂直域</strong></td><td>特定的<strong>系统族</strong>，包含整个系统族内的多个系统</td><td>整个系统族</td></tr><tr><td><strong>水平域</strong></td><td>多个系统族中功能区域的<strong>共有部分</strong></td><td>子系统级</td></tr></tbody></table><h4 id="dssa-特征" tabindex="-1">DSSA 特征 <a class="header-anchor" href="#dssa-特征" aria-label="Permalink to &quot;DSSA 特征&quot;">​</a></h4><ol><li>严格定义的问题域和解决域</li><li>具有<strong>普遍性</strong></li><li>对领域有合适程度的抽象</li><li>具备固定典型开发过程中的<strong>可重用元素</strong></li></ol><blockquote><p>⚠️ &quot;随机性&quot; 不属于 DSSA 特征。</p></blockquote><h4 id="建立dssa的过程" tabindex="-1">建立DSSA的过程 <a class="header-anchor" href="#建立dssa的过程" aria-label="Permalink to &quot;建立DSSA的过程&quot;">​</a></h4><ul><li>(1)定义领域范围：领域中的应用要满足用户一系列的需求。</li><li>(2)定义领域特定的元素：<strong>建立领域的字典，归纳领域中的术语</strong>，识别出领域中相同和不相同的元素。</li><li>(3)定义领域特定的设计和实现需求的<strong>约束</strong>：识别领域中的所有约束，这些约束对领域的设计和实现会造成什么后果。</li><li>(4)定义<strong>领域模型和架构</strong>：产生一般的架构，并描述其构件说明。</li><li>(5)产生、搜集可复用的产品单元：为DSSA增加复用构件，使可用于新的系统：</li></ul><p>以上过程是<strong>并发的、递归的、反复的、螺旋型的</strong>。该过程的目的是将用户的需求映射为基于实现限制集合的软件需求，这些需求定义了DSSA。</p><h4 id="dssa的三层次系统模型" tabindex="-1">DSSA的三层次系统模型 <a class="header-anchor" href="#dssa的三层次系统模型" aria-label="Permalink to &quot;DSSA的三层次系统模型&quot;">​</a></h4><p>领域开发环境：<strong>领域架构师决定核心架构</strong>，产出参考结构、参考需求、架构、领域模型、开发工具。</p><p>领域特定的应用开发环境：应用工程师根据具体环境来将核心架构实例化。</p><p>应用执行环境：操作员实现实例化后的架构。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517144433.png" alt="image.png"></p><hr><h3 id="_4-1-视图模型" tabindex="-1">4+1 视图模型 <a class="header-anchor" href="#_4-1-视图模型" aria-label="Permalink to &quot;4+1 视图模型&quot;">​</a></h3><blockquote><p>4+1 视图模型从多个视图描述软件体系结构，核心思想是<strong>关注点分离</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>视图</th><th>作用</th><th>关注点</th></tr></thead><tbody><tr><td><strong>逻辑视图</strong></td><td>描述对象模型，说明系统应提供哪些服务</td><td>功能需求（用户视角）</td></tr><tr><td><strong>过程视图</strong></td><td>捕捉设计的<strong>并发和同步</strong>特性</td><td>系统行为特性（动态视角）</td></tr><tr><td><strong>开发视图</strong></td><td>描述开发环境中软件的<strong>静态组织结构</strong></td><td>模块组织</td></tr><tr><td><strong>物理视图</strong></td><td>描述软件到硬件的映射</td><td>部署拓扑</td></tr><tr><td><strong>场景（+1）</strong></td><td><strong>用例视图</strong>，验证其他视图一致性</td><td>统一场景</td></tr></tbody></table><p><strong>视图与视角关系：</strong></p><ul><li><strong>静态视角</strong>（展示功能组织）→ 判断质量特性</li><li><strong>动态视角</strong>（展示并发行为）→ 判断系统行为特性</li><li>四个视图：逻辑视图、进程视图、实现视图、<strong>配置视图</strong></li><li>使用<strong>逻辑视图</strong>记录设计元素的功能和概念接口</li></ul><hr><blockquote><p>多视图体现了<strong>关注点分离</strong>的思想。&quot;4+1&quot;模型中的&quot;1&quot;指的是<strong>统一场景（Use Case）</strong>，将 4 个视图（逻辑视图、进程视图、开发视图、物理视图）串联起来。</p></blockquote><hr><h4 id="软件系统四项基本功能-划分视角" tabindex="-1">软件系统四项基本功能（划分视角） <a class="header-anchor" href="#软件系统四项基本功能-划分视角" aria-label="Permalink to &quot;软件系统四项基本功能（划分视角）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>视角</th><th>关注点</th><th style="text-align:center;">能否判断质量特性</th></tr></thead><tbody><tr><td><strong>静态视角（逻辑视图）</strong></td><td>功能组织</td><td style="text-align:center;">✅</td></tr><tr><td><strong>动态视角（进程视图）</strong></td><td>并发行为 → 系统行为特性</td><td style="text-align:center;">✅</td></tr><tr><td><strong>配置视角（部署视图）</strong></td><td>软件到硬件的映射</td><td style="text-align:center;">❌</td></tr></tbody></table><hr><hr><h3 id="软件复用" tabindex="-1">软件复用 <a class="header-anchor" href="#软件复用" aria-label="Permalink to &quot;软件复用&quot;">​</a></h3><p><strong>机会复用 vs 系统复用：</strong></p><ul><li><strong>机会复用</strong>（发现复用）：开发过程中，只要发现有可复用的资产，就进行复用</li><li><strong>系统复用</strong>（计划复用）：开发之前就进行规划，决定哪些需要复用</li></ul><p><strong>水平式重用 vs 垂直式重用：</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>特点</th><th>典型代表</th></tr></thead><tbody><tr><td><strong>水平式重用</strong></td><td>跨领域通用（应用领域无关），提供基础功能</td><td>标准函数库、通用类库</td></tr><tr><td><strong>垂直式重用</strong></td><td>面向特定领域（领域相关），包含领域知识</td><td>医学词汇表、电子商务标准、网银支付接口</td></tr></tbody></table><p><strong>复用过程的三个主要阶段：</strong></p><ol><li>构造/获取可复用的软件资产</li><li>管理可复用资产</li><li>使用可复用资产</li></ol><hr><h3 id="架构复审与演化" tabindex="-1">架构复审与演化 <a class="header-anchor" href="#架构复审与演化" aria-label="Permalink to &quot;架构复审与演化&quot;">​</a></h3><p><strong>架构复审目的：</strong> 标识潜在风险，及早发现架构设计中的缺陷和错误。复审过程中主要由<strong>用户代表与领域专家</strong>决定架构是否满足需求、质量需求是否在设计中得到体现。</p><p><strong>架构演化：</strong> 针对用户需求变化，修改应用架构满足新的需求。</p><p><strong>架构描述与需求对应：</strong></p><ul><li>架构 → 用<strong>视角与视图</strong>描述</li><li>功能需求 → 用<strong>用例</strong>描述</li><li>质量需求 → 用<strong>质量场景</strong>描述</li></ul><hr><h3 id="构件组装与架构失配" tabindex="-1">构件组装与架构失配 <a class="header-anchor" href="#构件组装与架构失配" aria-label="Permalink to &quot;构件组装与架构失配&quot;">​</a></h3><blockquote><p>🎯 架构失配主要包括三类：<strong>构件失配</strong>（基础设施/控制模型/数据模型冲突）、<strong>连接子失配</strong>（交互协议/数据格式冲突）、<strong>系统成分对全局体系结构的假设冲突</strong>。</p></blockquote><p><strong>失配分类与原因：</strong></p><table tabindex="0"><thead><tr><th>失配类型</th><th>产生原因</th><th>关键词</th></tr></thead><tbody><tr><td><strong>构件失配</strong></td><td>系统对构件基础设施、控制模型和数据模型的假设存在冲突</td><td>基础设施、控制模型、数据模型</td></tr><tr><td><strong>连接子失配</strong></td><td>系统对构件交互协议、构件连接时数据格式的假设存在冲突</td><td>交互协议、数据格式</td></tr><tr><td><strong>全局体系结构失配</strong></td><td>系统成分对全局体系结构的假设存在冲突</td><td>整体架构假设</td></tr></tbody></table><blockquote><p>⚠️ 常见坑：<strong>由构件操作不当引起的失配</strong>不属于构件组装阶段的失配问题。</p></blockquote><hr><h3 id="软件系统四大基本功能-三硬件构件-架构设计核心模型" tabindex="-1">软件系统四大基本功能 + 三硬件构件（架构设计核心模型） <a class="header-anchor" href="#软件系统四大基本功能-三硬件构件-架构设计核心模型" aria-label="Permalink to &quot;软件系统四大基本功能 + 三硬件构件（架构设计核心模型）&quot;">​</a></h3><blockquote><p>🎯 软件系统可分为四项基本功能，硬件有三类主要构件。架构设计的首要步骤是将<strong>非功能需求</strong>细化为更详细的需求。</p></blockquote><p><strong>软件系统四大基本功能（自上而下）：</strong></p><table tabindex="0"><thead><tr><th>功能</th><th>英文</th><th>说明</th></tr></thead><tbody><tr><td><strong>数据存储</strong></td><td>Data Storage</td><td>存储和检索数据，无论是小文件还是大数据库</td></tr><tr><td><strong>数据访问逻辑</strong></td><td>Data Access Logic</td><td>处理访问数据的过程，通常指 SQL 查询</td></tr><tr><td><strong>应用逻辑</strong></td><td>Application Logic</td><td>DFD、用例和功能需求中记录的业务逻辑</td></tr><tr><td><strong>表示逻辑</strong></td><td>Presentation Logic</td><td>向用户显示信息并接收用户命令</td></tr></tbody></table><p><strong>系统三类主要硬件构件：</strong></p><blockquote><p>🎯 客户端（Clients）、服务器（Servers）、网络（Network）。</p></blockquote><hr><h3 id="设计模式三分类" tabindex="-1">设计模式三分类 <a class="header-anchor" href="#设计模式三分类" aria-label="Permalink to &quot;设计模式三分类&quot;">​</a></h3><blockquote><p>🎯 设计模式按目的分为：<strong>创建型</strong>（对象实例化）、<strong>结构型</strong>（类/对象组合）、<strong>行为型</strong>（类/对象交互）。</p></blockquote><table tabindex="0"><thead><tr><th>分类</th><th>核心关注</th><th>典型例子</th></tr></thead><tbody><tr><td><strong>创建型</strong></td><td>对象实例化过程的抽象</td><td>单例（Singleton）、工厂方法</td></tr><tr><td><strong>结构型</strong></td><td>类或对象的组合方式</td><td>适配器（Adapter）、桥接（Bridge）</td></tr><tr><td><strong>行为型</strong></td><td>类或对象之间的交互和职责分配</td><td>策略（Strategy）、观察者（Observer）</td></tr></tbody></table><blockquote><p>🎯 Bridge 模式 = 将抽象与实现分离；Strategy 模式 = 算法族可互换使用。飞机模拟系统中飞行行为与起飞行为的解耦是 <strong>Strategy 模式</strong>。</p></blockquote>',63))])}const m=a(h,[["render",b]]);export{f as __pageData,m as default};
